/**
 * Validate that a string is a date in YYYY-MM-DD format.
 * All dates are in UTC.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const [year, month, day] = text.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date instanceof Date && !isNaN(date) && date.toISOString().startsWith(text);
}

/**
 * Add n days to a date (in UTC).
 * @param {string} date - Date in YYYY-MM-DD format
 * @param {number} n - Number of days to add (can be negative)
 * @returns {string} - Date in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const [year, month, day] = date.split('-').map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + n);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}

/**
 * Calculate the number of whole days between two dates (b minus a).
 * Both dates are in YYYY-MM-DD format, arithmetic is in UTC.
 * @param {string} a - First date in YYYY-MM-DD format
 * @param {string} b - Second date in YYYY-MM-DD format
 * @returns {number} - Number of days (b - a)
 */
export function daysBetween(a, b) {
  const [ya, ma, da] = a.split('-').map(Number);
  const [yb, mb, db] = b.split('-').map(Number);
  const dateA = new Date(Date.UTC(ya, ma - 1, da));
  const dateB = new Date(Date.UTC(yb, mb - 1, db));
  const diffMs = dateB - dateA;
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

